'use strict';
const DEMO=document.body.dataset.demo==='true';
const ROOT=new URL('../',location.href);
const $=(s,r=document)=>r.querySelector(s);
const $$=(s,r=document)=>Array.from(r.querySelectorAll(s));
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const parse=html=>new DOMParser().parseFromString(html,'text/html');
const iso=()=>new Date().toISOString();
const titleOf=html=>parse(html).title.replace(/\s*\|\s*Next Chapter Collective\s*$/,'').trim();
const pageLabel=slug=>slug==='index'?'Home':slug.split('-').map(w=>w[0].toUpperCase()+w.slice(1)).join(' ');
const dateLabel=value=>new Date(value).toLocaleDateString(undefined,{month:'short',day:'numeric'});
const state={view:'dashboard',pages:[],media:[],settings:{},csrf:'',current:null,scope:'page',selected:null,section:null,undo:[],sharedHeader:false,sharedFooter:false,dirty:false,tab:'content',filter:'all',menu:[],menuPage:null};
let demoStore,toastTimer,richRange=null,pendingMedia=null;
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className='toast show'+(error?' error':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.className='toast',5000)}
function modal(title,body,footer='',wide=false){const dialog=$('#modal');dialog.classList.toggle('wide',wide);$('#modal-content').innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button class="btn ghost sm" data-modal-close type="button" aria-label="Close dialog">✕</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-foot">${footer}</div>`:''}`;if(!dialog.open)dialog.showModal();return dialog}
function closeModal(){$('#modal').close();pendingMedia=null}
async function confirmAction(title,message,label='Continue'){return new Promise(resolve=>{modal(title,`<p class="small muted">${esc(message)}</p>`,`<button class="btn" data-confirm="no">Cancel</button><button class="btn primary" data-confirm="yes">${esc(label)}</button>`);$$('[data-confirm]').forEach(b=>b.onclick=()=>{closeModal();resolve(b.dataset.confirm==='yes')});$('#modal').addEventListener('cancel',()=>resolve(false),{once:true});$('[data-modal-close]').onclick=()=>{closeModal();resolve(false)}})}
async function api(action,data=null,params={}){
 if(DEMO)return demoApi(action,data,params);
 const query=new URLSearchParams({action,...params});const options={credentials:'same-origin',cache:'no-store',headers:{Accept:'application/json'}};
 if(data!==null){options.method='POST';options.headers['X-CSRF-Token']=state.csrf;if(data instanceof FormData)options.body=data;else{options.headers['Content-Type']='application/json';options.body=JSON.stringify(data)}}
 const response=await fetch('api.php?'+query,options);let result;try{result=await response.json()}catch{throw Error('The admin server is unavailable. Open the PHP admin address on Hostinger, or use the local preview link.')}
 if(!response.ok||!result.success)throw Error(result.message||'The request could not be completed.');if(result.csrf)state.csrf=result.csrf;return result;
}
function persistDemo(){localStorage.setItem('ncc-admin-demo-v1',JSON.stringify(demoStore))}
function demoPages(){return Object.entries(demoStore.pages).map(([slug,p])=>({slug,title:titleOf(p.draft||p.published),status:p.published?'published':'draft',hasDraft:!!p.draft,updated:p.updated,revision:p.published?'demo-published':''}))}
function demoPage(slug){const p=demoStore.pages[slug];if(!p)throw Error('This page was not found.');return {slug,title:titleOf(p.draft||p.published),html:p.draft||p.published,revision:p.published?'demo-published':'',draft_revision:p.draft?'demo-draft':'',hasDraft:!!p.draft,published:!!p.published,updated:p.updated,sharedHeader:p.sharedHeader,sharedFooter:p.sharedFooter}}
async function initDemo(){try{demoStore=JSON.parse(localStorage.getItem('ncc-admin-demo-v1'))}catch{}if(!demoStore){demoStore={pages:{},trash:[],settings:{siteName:'Next Chapter Collective',recipient_email:'',sender_email:'',username:'Site owner'}};for(const slug of ['index','training','technology-advisory','mentoring','about','mentors','contact','privacy']){const r=await fetch(new URL(slug+'.html',ROOT));if(!r.ok)throw Error('The preview could not load '+slug+'.html');demoStore.pages[slug]={published:await r.text(),draft:'',updated:iso()}}persistDemo()}
 const files=[['mentoring-session.webp',1536,1024,123254],['corporate-workshop.webp',1536,1024,130142],['technology-guidance.webp',1536,1024,123842]];state.media=files.map(([name,width,height,bytes])=>({name,width,height,bytes,url:'assets/images/'+name,updated:iso()}));state.pages=demoPages();state.settings=demoStore.settings;$('#user-name').textContent='Site owner';$('#mode-badge').hidden=false;$('#demo-notice').hidden=false;$('#auth-screen').hidden=true;$('#admin-app').hidden=false;renderView('dashboard')}
async function demoApi(action,data,params){
 if(action==='state')return {pages:demoPages(),media:state.media,settings:demoStore.settings};
 if(action==='page')return {page:demoPage(params.slug)};
 if(action==='draft'){const p=demoStore.pages[data.slug];p.draft=data.html;p.sharedHeader=!!data.sharedHeader;p.sharedFooter=!!data.sharedFooter;p.updated=iso();persistDemo();return {page:demoPage(data.slug),pages:demoPages()}}
 if(action==='create'){if(demoStore.pages[data.slug])throw Error('That page address is already in use.');const doc=parse(demoStore.pages.index.published);$('main',doc).innerHTML=`<section class="section container"><h1>${esc(data.title)}</h1><p>Add your page content here.</p></section>`;doc.title=data.title+' | Next Chapter Collective';demoStore.pages[data.slug]={published:'',draft:'<!doctype html>'+doc.documentElement.outerHTML,updated:iso()};persistDemo();return {page:demoPage(data.slug),pages:demoPages()}}
 if(action==='discard'){demoStore.pages[data.slug].draft='';persistDemo();return {page:demoPage(data.slug),pages:demoPages()}}
 if(action==='trash'){if(data.slug==='index')throw Error('The homepage cannot be moved to Trash.');demoStore.trash.push({id:data.slug+'-'+Date.now(),slug:data.slug,title:demoPage(data.slug).title,updated:iso(),record:demoStore.pages[data.slug]});delete demoStore.pages[data.slug];persistDemo();return {pages:demoPages()}}
 if(action==='trash_list')return {items:demoStore.trash};
 if(action==='restore_trash'){const item=demoStore.trash.find(x=>x.id===data.id);if(demoStore.pages[item.slug])throw Error('That address is already in use.');demoStore.pages[item.slug]={published:'',draft:item.record.draft||item.record.published,updated:iso()};demoStore.trash=demoStore.trash.filter(x=>x!==item);persistDemo();return {pages:demoPages(),page:demoPage(item.slug)}}
 if(action==='revisions')return {revisions:[]};
 if(action==='settings'){demoStore.settings={...demoStore.settings,...data};persistDemo();return {settings:demoStore.settings}}
 if(action==='menu'){Object.values(demoStore.pages).forEach(p=>{const doc=parse(p.published||p.draft);const nav=$('#navigation',doc);if(nav)nav.replaceChildren(...buildMenuNodes(doc,data.items));p.draft='<!doctype html>'+doc.documentElement.outerHTML;p.updated=iso()});persistDemo();return {pages:demoPages(),page:demoPage('index')}}
 if(action==='publish'||action==='upload'||action==='password')throw Error('This action is available after setting up the PHP admin console on Hostinger.');
 if(action==='logout')return {};
 throw Error('This action is not available in the local preview.');
}
async function boot(){if(DEMO){try{await initDemo()}catch(e){$('#auth-error').textContent=e.message}return}try{const r=await api('bootstrap');state.csrf=r.csrf;if(r.authenticated){$('#user-name').textContent=r.username;await enterApp()}else renderAuth(r.setupRequired,r.requirements)}catch(e){$('#auth-error').textContent=e.message}}
function renderAuth(setup,requirements={}){$('#auth-screen').hidden=false;$('#admin-app').hidden=true;$('#setup-key-label').hidden=!setup;$('#setup-key-label input').required=setup;$('#auth-title').textContent=setup?'Make it your workspace.':'Welcome back.';$('#auth-intro').textContent=setup?'Use the private owner setup key supplied with your website, then choose your username and password.':'Sign in to manage your website.';$('#auth-submit').textContent=setup?'Create owner account':'Sign in';$('#auth-form').dataset.mode=setup?'setup':'login';const pass=$('#auth-form [name="password"]');pass.autocomplete=setup?'new-password':'current-password';pass.minLength=setup?12:1;if(setup)$('#auth-note').textContent='Choose a password with at least 12 characters. Keep ADMIN-SETUP.txt outside your public website folder.';if(Object.values(requirements).some(v=>v===false))$('#auth-error').textContent='Your hosting needs PHP OpenSSL, DOM, Fileinfo and image functions, plus writable website storage. Enable these before setup.'}
async function enterApp(){const r=await api('state');state.pages=r.pages;state.media=r.media;state.settings=r.settings;$('#auth-screen').hidden=true;$('#admin-app').hidden=false;renderView('dashboard')}
function header(title,description,actions='',kicker=''){return `<div class="view-header"><div>${kicker?`<p class="overline">${kicker}</p>`:''}<h1>${title}</h1><p>${description}</p></div>${actions?`<div class="button-row">${actions}</div>`:''}</div>`}
function setActive(view){state.view=view;$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));document.body.classList.remove('sidebar-open')}
async function safeNavigate(view){if(state.dirty&&!await confirmAction('Leave this edit?','You have unsaved changes. Save your changes first if you want to keep them.','Leave editor'))return;state.dirty=false;renderView(view)}
function renderView(view){setActive(view);const main=$('#view');if(view==='dashboard')renderDashboard();else if(view==='pages')renderPages();else if(view==='media')renderMedia();else if(view==='menus')loadMenus();else if(view==='shared')renderShared();else if(view==='settings')renderSettings();else if(view==='trash')renderTrash();else if(view==='help')renderHelp();else main.innerHTML='';window.scrollTo({top:0,behavior:'instant'})}
function pageRows(pages,compact=false){return pages.map(p=>`<tr><td><button class="page-title-link" data-edit="${esc(p.slug)}">${esc(p.slug==='index'?'Home':p.title)}</button><span class="page-slug">/${p.slug==='index'?'':esc(p.slug)+'.html'}</span></td><td><span class="status ${p.status==='draft'?'draft':''}">${p.status==='draft'?'Draft':'Published'}</span>${p.hasDraft&&p.status==='published'?'<span class="page-slug">Draft changes saved</span>':''}</td><td class="hide-phone">${dateLabel(p.updated)}</td><td><div class="row-actions"><button data-edit="${esc(p.slug)}">Edit</button>${!compact&&p.slug!=='index'?`<button class="danger-link" data-trash="${esc(p.slug)}">Trash</button>`:''}</div></td></tr>`).join('')}
function renderDashboard(){const published=state.pages.filter(p=>p.status==='published').length,drafts=state.pages.filter(p=>p.hasDraft).length;$('#view').innerHTML=header('A good place to move things forward.','Make a small update, shape a new page, or plan your next chapter.','<button class="btn primary" data-action="new-page">＋ Add a page</button>','WELCOME TO YOUR WORKSPACE')+`<div class="stats-grid"><div class="stat"><span>Published pages</span><strong>${published}</strong><small>Your website, ready to explore</small><i>▤</i></div><div class="stat"><span>Saved drafts</span><strong>${drafts}</strong><small>Changes you can come back to</small><i>▱</i></div><div class="stat"><span>Media library</span><strong>${state.media.length}</strong><small>Images for your next update</small><i>▧</i></div><div class="stat"><span>Shared areas</span><strong>2</strong><small>Header and footer, across pages</small><i>◫</i></div></div><div class="dashboard-columns"><section class="panel"><div class="panel-header"><h2>Your pages</h2><button class="text-button" data-view="pages">View all →</button></div><table class="page-table"><thead><tr><th>PAGE</th><th>STATUS</th><th class="hide-phone">UPDATED</th><th></th></tr></thead><tbody>${pageRows(state.pages.slice(0,6),true)}</tbody></table><div class="panel-footer"><button class="text-button" data-action="new-page">＋ Create something new</button></div></section><div><section class="panel"><div class="panel-header"><h2>Make it yours</h2></div><div class="panel-body"><div class="quick-action"><span class="quick-icon">↗</span><div><h3>Refresh your homepage</h3><p>Update the words, photos and sections.</p></div><button class="text-button" data-edit="index" aria-label="Edit homepage">→</button></div><div class="quick-action"><span class="quick-icon">☷</span><div><h3>Shape your navigation</h3><p>Add links and organize dropdowns.</p></div><button class="text-button" data-view="menus" aria-label="Edit navigation">→</button></div><div class="quick-action"><span class="quick-icon">▧</span><div><h3>Bring in a new image</h3><p>Find a photo in your media library.</p></div><button class="text-button" data-view="media" aria-label="Open media library">→</button></div></div></section><section class="panel help-panel"><div class="panel-body"><p class="overline">A LITTLE GUIDANCE</p><h2>Click a section.<br>Make it your own.</h2><p>The visual editor helps you update text, pictures and page sections while keeping your website’s design in view.</p><button class="btn" data-view="help">Explore the editing guide →</button></div></section></div></div>`}
function renderPages(){const pages=state.pages.filter(p=>state.filter==='all'||(state.filter==='draft'?p.hasDraft:p.status==='published'));$('#view').innerHTML=header('Pages','All the places your next chapter lives.','<button class="btn primary" data-action="new-page">＋ Add a page</button>')+`<div class="table-toolbar"><div class="filter-tabs"><button data-page-filter="all" class="${state.filter==='all'?'active':''}">All pages (${state.pages.length})</button><button data-page-filter="published" class="${state.filter==='published'?'active':''}">Published</button><button data-page-filter="draft" class="${state.filter==='draft'?'active':''}">Drafts</button></div><input id="page-search" class="search-input" type="search" placeholder="Search pages…" aria-label="Search pages"></div><div class="panel"><table class="page-table"><thead><tr><th>PAGE</th><th>STATUS</th><th class="hide-phone">UPDATED</th><th>ACTIONS</th></tr></thead><tbody id="page-rows">${pageRows(pages)}</tbody></table>${pages.length?'':'<p class="empty-message">No pages match this view.</p>'}</div>`;$('#page-search').oninput=e=>$('#page-rows').innerHTML=pageRows(pages.filter(p=>(p.title+' '+p.slug).toLowerCase().includes(e.target.value.toLowerCase())))}
function renderMedia(){ $('#view').innerHTML=header('Media Library','The images that bring your website to life.',`<button class="btn primary" data-action="upload" ${DEMO?'disabled title="Uploads are available after Hostinger setup"':''}>＋ Upload images</button>`)+`<div class="media-toolbar"><p class="small muted" style="margin:0">${state.media.length} images · JPG, PNG, WebP and GIF</p><input id="media-search" class="search-input" type="search" placeholder="Search images…" aria-label="Search images"></div><div class="media-grid" id="media-grid">${mediaCards(state.media)}</div>`;$('#media-search').oninput=e=>$('#media-grid').innerHTML=mediaCards(state.media.filter(x=>x.name.toLowerCase().includes(e.target.value.toLowerCase())))}
function mediaCards(items,picker=false){return items.map(m=>`<button class="media-card" ${picker?'data-pick-media':'data-media-detail'}="${esc(m.url)}"><img src="${esc(new URL(m.url,ROOT))}" alt="${esc(m.name)}" loading="lazy"><div><strong>${esc(m.name)}</strong><small>${m.width} × ${m.height} · ${Math.round(m.bytes/1024)} KB</small></div></button>`).join('')}
function openMediaPicker(callback){pendingMedia=callback;modal('Choose an image',`<div class="button-row" style="margin-bottom:18px"><span class="small muted">Choose a photo from your media library.</span><span class="spacer"></span><button class="btn sm" data-action="upload" ${DEMO?'disabled':''}>＋ Upload image</button></div><div class="media-grid">${mediaCards(state.media,true)}</div>`,'',true)}
function showMediaDetail(url){const m=state.media.find(x=>x.url===url);modal('Image details',`<img src="${esc(new URL(m.url,ROOT))}" alt="${esc(m.name)}" style="width:100%;max-height:300px;object-fit:contain;background:#f3f4f7;margin-bottom:22px"><label>File name<input value="${esc(m.name)}" readonly></label><p class="small muted">${m.width} × ${m.height} pixels · ${Math.round(m.bytes/1024)} KB</p><label>Image path<input value="${esc(m.url)}" readonly></label><p class="small muted">To replace an image, open a page and click its photo in the visual editor. Alternative text is edited on each page, so it can describe that image in context.</p>`)}
async function newPageDialog(){modal('Create a new page','<label>Page title<input id="new-title" placeholder="For example: Our Programs" autofocus></label><label>Page address<input id="new-slug" placeholder="our-programs" spellcheck="false"><small>Use lowercase letters, numbers and hyphens. The page starts as a private draft.</small></label>','<button class="btn" data-modal-close>Cancel</button><button class="btn primary" data-action="create-page">Create draft</button>');$('#new-title').oninput=e=>$('#new-slug').value=e.target.value.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')}
async function createPage(){const title=$('#new-title').value.trim(),slug=$('#new-slug').value.trim();if(!title||!/^[a-z][a-z0-9-]{0,63}$/.test(slug))return toast('Enter a title and a valid page address.',true);const r=await api('create',{title,slug});state.pages=r.pages;closeModal();loadEditor(r.page)}
async function openEditor(slug,scope='page'){if(state.dirty&&!await confirmAction('Leave this edit?','You have unsaved changes. Save your changes first if you want to keep them.','Leave editor'))return;const r=await api('page',null,{slug});loadEditor(r.page,scope)}
function loadEditor(page,scope='page'){setActive(scope==='page'?'pages':'shared');state.current=page;state.scope=scope;state.selected=null;state.section=null;state.dirty=false;state.sharedHeader=!!page.sharedHeader;state.sharedFooter=!!page.sharedFooter;state.undo=[];state.tab='content';state.heroIndex=0;$('#view').innerHTML=`<div class="editor-shell"><div class="editor-top"><div class="editor-title"><button class="back-button" data-view="pages" aria-label="Back to pages">←</button><div><h1>${esc(pageLabel(page.slug))}</h1><p>/${page.slug==='index'?'':esc(page.slug)+'.html'} <span id="dirty-label">${page.hasDraft?'· Saved draft':'· '+(page.published?'Published':'Draft')}</span></p></div></div><div class="editor-controls"><button class="btn" data-action="undo">↶ Undo</button><button class="btn" data-action="save-draft">Save draft</button><button class="btn primary" data-action="publish" ${DEMO?'disabled title="Publishing is available after Hostinger setup"':''}>Publish changes ↗</button></div></div><div class="editor-bar"><select id="edit-scope" aria-label="Editing area"><option value="page">Page sections</option><option value="header">Shared header & menu</option><option value="footer">Shared footer</option></select>${page.slug==='index'?'<select id="hero-feature" aria-label="Hero feature"><option value="0">Hero feature 1</option><option value="1">Hero feature 2</option><option value="2">Hero feature 3</option></select>':''}<span id="scope-note">Click text or a photo in the preview to edit it.</span><div class="button-row"><button class="btn sm" data-preview-size="desktop">Desktop</button><button class="btn sm" data-preview-size="phone">Phone</button></div></div><div class="editor-grid"><aside class="section-list"><div class="section-list-head"><span id="section-count">Sections</span><span>☷</span></div><div class="section-items" id="section-items"></div><div class="section-list-foot"><button class="btn" data-action="add-section">＋ Add section</button></div></aside><section class="preview-area"><div class="preview-title"><span><i></i><i></i><i></i></span><span>VISUAL EDITOR</span><span>↗</span></div><div class="preview-wrap" id="preview-wrap"><iframe id="page-preview" title="Website visual editor" sandbox="allow-same-origin"></iframe></div></section><aside class="inspector"><div class="inspector-header"><span>Make it your own</span><span id="selected-label" class="selected-type">SELECT A BLOCK</span></div><div class="inspector-tabs"><button data-inspector="content" class="active">Content</button><button data-inspector="page">Page</button><button data-inspector="history">History</button><button data-inspector="html">HTML</button></div><div class="inspector-body" id="inspector-body"></div></aside></div></div>`;$('#edit-scope').value=scope;$('#edit-scope').onchange=e=>{state.scope=e.target.value;state.selected=null;state.section=null;renderOutline();renderInspector();$('#scope-note').textContent=state.scope==='page'?'Click text or a photo in the preview to edit it.':'Edits to this area apply to every published page when you publish.'};mountPreview(page.html);if($('#hero-feature'))$('#hero-feature').onchange=e=>{syncHero();state.heroIndex=Number(e.target.value);showEditorHero();};renderInspector()}
function mountPreview(html){state.heroIndex=0;if($('#hero-feature'))$('#hero-feature').value='0';const doc=parse(html);$$('script,base',doc).forEach(n=>n.remove());const base=doc.createElement('base');base.href=ROOT.href;base.dataset.cmsPreview='';doc.head.prepend(base);const style=doc.createElement('style');style.dataset.cmsPreview='';style.textContent='[data-cms-selected]{outline:2px solid #f47745!important;outline-offset:4px!important}[data-cms-hover]:not([data-cms-selected]){outline:1px dashed #ffae85!important;outline-offset:3px!important}html{scroll-behavior:auto!important}body{cursor:default}';doc.head.append(style);const frame=$('#page-preview');frame.onload=()=>{const d=frame.contentDocument;d.addEventListener('click',onPreviewClick,true);d.addEventListener('submit',e=>e.preventDefault(),true);d.addEventListener('mouseover',e=>{$$('[data-cms-hover]',d).forEach(x=>x.removeAttribute('data-cms-hover'));const root=editableRoot(e.target);if(root)e.target.setAttribute('data-cms-hover','')});d.addEventListener('mouseout',e=>{if(e.target.nodeType===1)e.target.removeAttribute('data-cms-hover')});renderOutline();$('#scope-note').textContent=state.scope==='page'?'Click text or a photo in the preview to edit it.':'Edits to this area apply to every published page when you publish.'};frame.srcdoc='<!doctype html>'+doc.documentElement.outerHTML}
function previewDoc(){return $('#page-preview')?.contentDocument}
function editableRoot(target){if(!target||target.nodeType!==1)return null;return target.closest(state.scope==='page'?'main':state.scope==='header'?'.site-header,.utility-bar':'footer')}
function topSection(target){const d=previewDoc();if(state.scope==='header')return target.closest('.site-header,.utility-bar');if(state.scope==='footer')return target.closest('footer');const main=$('main',d);let node=target;while(node&&node.parentElement!==main)node=node.parentElement;return node&&node.parentElement===main?node:null}
function onPreviewClick(event){event.preventDefault();event.stopPropagation();const target=event.target;if(!editableRoot(target))return;let selected;if(target.tagName==='IMG')selected=target;else if(target.matches('input,select,textarea'))selected=target;else{selected=target.closest('h1,h2,h3,h4,h5,h6,p,li,blockquote,figcaption,summary')||target.closest('a,small,strong,em,span,button,label')||target;if(selected.querySelector('input,select,textarea')){const text=Array.from(selected.childNodes).find(n=>n.nodeType===3&&n.textContent.trim());if(text){const span=selected.ownerDocument.createElement('span');span.dataset.cmsText='';text.replaceWith(span);span.append(text);selected=span}else selected=selected.querySelector('input,select,textarea')}}selectElement(selected)}
function selectElement(el){if(!el)return;const d=previewDoc();$$('[data-cms-selected]',d).forEach(x=>x.removeAttribute('data-cms-selected'));el.setAttribute('data-cms-selected','');state.selected=el;state.section=topSection(el);state.tab='content';renderOutline();renderInspector()}
function sectionNodes(){const d=previewDoc();if(!d)return[];if(state.scope==='header')return $$('.utility-bar,.site-header',d);if(state.scope==='footer')return $$('footer',d);return Array.from($('main',d)?.children||[])}
function sectionName(node,index){const title=$('h1,h2,h3',node)?.textContent.trim().replace(/\s+/g,' ');return title||node.getAttribute('aria-label')||node.className.split(' ').filter(x=>!['section','container'].includes(x)).join(' ').replace(/-/g,' ')||'Section '+(index+1)}
function renderOutline(){const nodes=sectionNodes();$('#section-count').textContent=(state.scope==='page'?'Sections':'Shared areas')+' · '+nodes.length;$('#section-items').innerHTML=nodes.map((node,i)=>`<button class="section-item ${node===state.section?'active':''} ${node.hidden?'dimmed':''}" data-section-index="${i}"><span>${String(i+1).padStart(2,'0')} ${node.hidden?'· HIDDEN':''}</span>${esc(sectionName(node,i).slice(0,65))}</button>`).join('');$('.section-list-foot').hidden=state.scope!=='page'}
function serializePage(){syncHero();const d=previewDoc();const clone=d.documentElement.cloneNode(true);const first=$('[data-hero-library] [data-feature]',clone);if(first){const h=$('#hero-heading',clone),p=$('#hero-description',clone),a=$('#hero-primary-link',clone),img=$('#hero-image',clone);if(h)h.innerHTML=$('h2',first).innerHTML;if(p)p.innerHTML=$('p',first).innerHTML;if(a){a.innerHTML=$('a',first).innerHTML+' <span aria-hidden="true">↗</span>';a.setAttribute('href',$('a',first).getAttribute('href'));}if(img){img.setAttribute('src',$('img',first).getAttribute('src'));img.alt=$('img',first).alt;}}$$('[data-cms-preview]',clone).forEach(n=>n.remove());$$('[data-cms-text]',clone).forEach(n=>n.replaceWith(...n.childNodes));$$('*',clone).forEach(el=>Array.from(el.attributes).forEach(a=>{if(a.name.startsWith('data-cms-'))el.removeAttribute(a.name)}));const head=$('head',clone);const script=d.createElement('script');script.src='assets/app.js?v=carousel2';script.defer=true;head.append(script);return '<!doctype html>'+clone.outerHTML}
function recordUndo(){state.undo.push(serializePage());if(state.undo.length>30)state.undo.shift()}
function dirty(){state.dirty=true;if(state.scope==='header')state.sharedHeader=true;if(state.scope==='footer')state.sharedFooter=true;$('#dirty-label').textContent='· Unsaved changes';$('#dirty-label').className='dirty-dot'}
function toolbar(){const heading=/^H[1-6]$/.test(state.selected?.tagName||'');return `<div class="rich-toolbar"><button type="button" data-rich="bold" title="Bold"><b>B</b></button><button type="button" data-rich="italic" title="Italic"><i>I</i></button><button type="button" data-rich="underline" title="Underline"><u>U</u></button><button type="button" data-rich="strikeThrough" title="Strikethrough"><s>S</s></button><button type="button" data-rich="insertUnorderedList" ${heading?'disabled':''} title="Bullet list">• ≡</button><button type="button" data-rich="insertOrderedList" ${heading?'disabled':''} title="Numbered list">1 ≡</button><button type="button" data-rich="justifyLeft" title="Align left">≡</button><button type="button" data-rich="justifyCenter" title="Align center">☰</button><button type="button" data-rich="createLink" title="Add link">↗</button><input type="color" id="rich-color" value="#f46f38" aria-label="Text color"><select id="rich-size" aria-label="Text size"><option value="">Size</option><option value="2">Small</option><option value="3">Normal</option><option value="4">Large</option><option value="5">Larger</option><option value="6">Heading</option></select><button type="button" data-rich="removeFormat" title="Clear formatting">Tx</button></div>`}
function sectionActions(){return state.section&&state.scope==='page'?`<div class="section-actions"><button class="btn" data-action="section-up">↑ Up</button><button class="btn" data-action="section-down">↓ Down</button><button class="btn" data-action="section-duplicate">Duplicate</button><button class="btn" data-action="section-hide">${state.section.hidden?'Show':'Hide'}</button><button class="btn danger" data-action="section-delete">Remove</button></div>`:''}
function renderInspector(){const body=$('#inspector-body');if(!body)return;$$('[data-inspector]').forEach(b=>b.classList.toggle('active',b.dataset.inspector===state.tab));const el=state.selected;$('#selected-label').textContent=el?el.tagName.toLowerCase():'SELECT A BLOCK';if(state.tab==='page')return renderPageProperties();if(state.tab==='history')return renderRevisions();if(state.tab==='html'){body.innerHTML='<p>Edit the full page HTML when you need precise control. Keep the header, main content area and one H1 heading.</p><textarea class="source-editor" id="page-source" aria-label="Page HTML"></textarea><button class="btn wide" data-action="apply-source">Apply HTML to preview</button>';$('#page-source').value=serializePage();return}
 if(!el){body.innerHTML=`<p>Choose a section from the list, or click any text or image in the page preview.</p><p><strong>Text:</strong> format words with bold, lists, links and color.</p><p><strong>Pictures:</strong> choose a new image and edit its description.</p><p><strong>Sections:</strong> reorder, duplicate, hide, remove or add a new layout.</p><button class="btn wide" data-action="add-section">＋ Add a section</button>`;return}
 if(el.tagName==='IMG'){body.innerHTML=`<img class="image-inspector-preview" src="${esc(new URL(el.getAttribute('src'),ROOT))}" alt="Selected image"><button class="btn wide" data-action="replace-image">Choose a different image</button><label style="margin-top:18px">Image description (alt text)<textarea id="image-alt" rows="3">${esc(el.getAttribute('alt')||'')}</textarea><small>Describe the image for people who cannot see it.</small></label><label>Image URL<input id="image-url" value="${esc(el.getAttribute('src')||'')}"></label><label>Crop position<select id="image-position"><option value="50% 50%">Center</option><option value="50% 0%">Top</option><option value="50% 100%">Bottom</option><option value="0% 50%">Left</option><option value="100% 50%">Right</option></select></label>${sectionActions()}`;$('#image-alt').oninput=e=>{recordUndo();el.setAttribute('alt',e.target.value);dirty()};$('#image-url').onchange=e=>{if(!validUrl(e.target.value,true))return toast('Use a local image path or an http/https URL.',true);recordUndo();el.src=e.target.value;dirty()};$('#image-position').value=el.style.objectPosition||'50% 50%';$('#image-position').onchange=e=>{recordUndo();el.style.objectPosition=e.target.value;dirty()};return}
 if(el.matches('input,select,textarea')){renderFieldInspector(el);return}
 const tagControl=/^(H[1-6]|P)$/.test(el.tagName)?`<label>Text style<select id="block-style">${['h1','h2','h3','h4','p'].map(t=>`<option value="${t}" ${el.tagName.toLowerCase()===t?'selected':''}>${t==='p'?'Paragraph':'Heading '+t.slice(1)}</option>`).join('')}</select></label>`:'';
 body.innerHTML=`${tagControl}<label style="margin-bottom:7px">${el===state.section?'Section content':'Text & formatting'}</label>${toolbar()}<div id="rich-editor" class="rich-editor" contenteditable="true" role="textbox" aria-multiline="true" aria-label="Rich text editor"></div>${el.tagName==='A'?`<label style="margin-top:17px">Link destination<input id="link-url" value="${esc(el.getAttribute('href')||'')}"></label><label class="check-label"><input type="checkbox" id="link-newtab" ${el.target==='_blank'?'checked':''}>Open in a new tab</label>`:''}<p class="field-description">Select words to format them. Changes appear in the page preview as you type.</p>${sectionActions()}`;
 const editor=$('#rich-editor');editor.innerHTML=el.innerHTML;$$('img',editor).forEach(img=>{img.dataset.editorSrc=img.getAttribute('src');img.src=new URL(img.getAttribute('src'),ROOT).href});editor.addEventListener('input',applyRichText);editor.addEventListener('keyup',captureRange);editor.addEventListener('mouseup',captureRange);editor.addEventListener('paste',event=>{event.preventDefault();document.execCommand('insertText',false,event.clipboardData.getData('text/plain'));applyRichText()});$$('[data-rich]').forEach(b=>b.addEventListener('mousedown',e=>e.preventDefault()));$('#rich-color').oninput=e=>runRich('foreColor',e.target.value);$('#rich-size').onchange=e=>{if(e.target.value)runRich('fontSize',e.target.value)};
 if($('#block-style'))$('#block-style').onchange=e=>{recordUndo();const replacement=el.ownerDocument.createElement(e.target.value);for(const a of Array.from(el.attributes))replacement.setAttribute(a.name,a.value);replacement.innerHTML=el.innerHTML;el.replaceWith(replacement);state.selected=replacement;dirty();renderOutline();renderInspector()};
 if($('#link-url'))$('#link-url').onchange=e=>{if(!validUrl(e.target.value))return toast('Use a page path, anchor, email, telephone or http/https URL.',true);recordUndo();el.setAttribute('href',e.target.value);dirty()};if($('#link-newtab'))$('#link-newtab').onchange=e=>{recordUndo();if(e.target.checked){el.target='_blank';el.rel='noopener noreferrer'}else{el.removeAttribute('target');el.removeAttribute('rel')}dirty()};
}
function validUrl(value,image=false){const v=value.trim();if(!v)return true;if(/[\x00-\x20\\<>]/.test(v)||v.startsWith('//')||/(^|\/)\.\.(\/|$)/.test(v))return false;const scheme=v.match(/^([a-z][a-z0-9+.-]*):/i);return !scheme||(image?['http','https']:['http','https','mailto','tel']).includes(scheme[1].toLowerCase())}
function captureRange(){const selection=getSelection();if(selection.rangeCount&&$('#rich-editor')?.contains(selection.anchorNode))richRange=selection.getRangeAt(0).cloneRange()}
function restoreRange(){const editor=$('#rich-editor');editor.focus();if(richRange){const selection=getSelection();selection.removeAllRanges();selection.addRange(richRange)}}
function applyRichText(){const editor=$('#rich-editor');if(!editor||!state.selected)return;recordUndo();const doc=parse('<div>'+editor.innerHTML+'</div>');$$('img[data-editor-src]',doc).forEach(img=>{img.setAttribute('src',img.dataset.editorSrc);img.removeAttribute('data-editor-src')});$$('script,iframe,object,embed',doc).forEach(n=>n.remove());$$('*',doc).forEach(n=>Array.from(n.attributes).forEach(a=>{if(a.name.startsWith('on')||(a.name==='href'&&!validUrl(a.value)))n.removeAttribute(a.name)}));state.selected.innerHTML=doc.body.firstElementChild.innerHTML;dirty();renderOutline()}
async function runRich(command,value=null){if(!$('#rich-editor'))return;if(command==='createLink'){captureRange();modal('Add a link','<label>Link destination<input id="rich-link-value" placeholder="contact.html or https://example.com"></label>','<button class="btn" data-modal-close>Cancel</button><button class="btn primary" data-action="insert-rich-link">Add link</button>');return}restoreRange();document.execCommand('styleWithCSS',false,true);document.execCommand(command,false,value);applyRichText();captureRange()}
function renderFieldInspector(el){const body=$('#inspector-body');body.innerHTML=`<p>Keep the field name unchanged so form delivery continues to work. Labels can be edited by clicking their text in the preview.</p><label>Placeholder<input id="field-placeholder" value="${esc(el.getAttribute('placeholder')||'')}"></label><label>Default value<input id="field-value" value="${esc(el.getAttribute('value')||el.value||'')}"></label>${el.tagName==='SELECT'?`<label>Options<textarea id="field-options" rows="7">${esc(Array.from(el.options).map(o=>(o.getAttribute('value')??o.textContent)+' | '+o.textContent).join('\n'))}</textarea><small>One option per line: value | visible label</small></label>`:''}<label class="check-label"><input id="field-required" type="checkbox" ${el.required?'checked':''}>Required field</label>${sectionActions()}`;$('#field-placeholder').oninput=e=>{recordUndo();el.setAttribute('placeholder',e.target.value);dirty()};$('#field-value').oninput=e=>{recordUndo();el.setAttribute('value',e.target.value);if(el.tagName==='TEXTAREA')el.textContent=e.target.value;dirty()};$('#field-required').onchange=e=>{recordUndo();el.required=e.target.checked;dirty()};if($('#field-options'))$('#field-options').onchange=e=>{recordUndo();el.replaceChildren();e.target.value.split('\n').filter(Boolean).forEach(line=>{const parts=line.split('|');const option=el.ownerDocument.createElement('option');option.value=parts.shift().trim();option.textContent=(parts.join('|')||option.value).trim();el.append(option)});dirty()}}
function renderPageProperties(){const d=previewDoc();const desc=$('meta[name="description"]',d)?.content||'';$('#inspector-body').innerHTML=`<label>Page title<input id="meta-title" value="${esc(d.title)}"></label><label>Search description<textarea id="meta-description" rows="5">${esc(desc)}</textarea><small>A short summary for search results and link previews.</small></label><label>Page address<input value="/${esc(state.current.slug)}.html" readonly><small>The address stays fixed to protect existing links.</small></label><p class="small">${state.current.published?'This page is currently published. Drafts do not change the public page.':'This is a draft page. It becomes public only when you publish it.'}</p>${state.current.hasDraft&&state.current.published?'<button class="btn wide" data-action="discard-draft">Discard saved draft</button>':''}`;$('#meta-title').oninput=e=>{recordUndo();d.title=e.target.value;const og=$('meta[property="og:title"]',d);if(og)og.content=e.target.value;dirty()};$('#meta-description').oninput=e=>{recordUndo();let meta=$('meta[name="description"]',d);if(!meta){meta=d.createElement('meta');meta.name='description';d.head.append(meta)}meta.content=e.target.value;const og=$('meta[property="og:description"]',d);if(og)og.content=e.target.value;dirty()}}
async function renderRevisions(){const body=$('#inspector-body');body.innerHTML='<p>Loading revisions…</p>';try{const r=await api('revisions',null,{slug:state.current.slug});if(state.tab!=='history')return;body.innerHTML=`<p>Publishing keeps up to 20 previous versions of each page. Restoring a version updates the public page.</p>${r.revisions.length?r.revisions.map(v=>`<div class="revision"><div><strong>${esc(v.title)}</strong><small>${new Date(v.updated).toLocaleString()}</small></div><button class="btn sm" data-restore-revision="${esc(v.id)}">Restore</button></div>`).join(''):`<p>${DEMO?'Revision history becomes available after Hostinger setup.':'No previous versions yet. Your first publish will create one.'}</p>`}`}catch(e){body.innerHTML=`<p class="error">${esc(e.message)}</p>`}}
async function saveDraft(){if(!state.current)return;const r=await api('draft',{slug:state.current.slug,html:serializePage(),revision:state.current.revision,draft_revision:state.current.draft_revision,sharedHeader:state.sharedHeader,sharedFooter:state.sharedFooter});state.current=r.page;state.pages=r.pages;state.dirty=false;$('#dirty-label').textContent='· Saved draft';$('#dirty-label').className='';toast(DEMO?'Draft saved in this browser. The public website is unchanged.':'Draft saved. The public website is unchanged.')}
async function publish(){if(DEMO)return toast('Publishing is available after Hostinger setup.',true);let message='These changes will update the public page.';if(state.sharedHeader||state.sharedFooter)message+=' Your shared '+[state.sharedHeader?'header':'',state.sharedFooter?'footer':''].filter(Boolean).join(' and ')+' changes will also apply to every published page.';if(!await confirmAction('Publish your changes?',message,'Publish changes'))return;const r=await api('publish',{slug:state.current.slug,html:serializePage(),revision:state.current.revision,sharedHeader:state.sharedHeader,sharedFooter:state.sharedFooter});state.pages=r.pages;loadEditor(r.page,state.scope);toast('Published successfully. '+r.updatedPages+' page'+(r.updatedPages===1?'':'s')+' updated.')}
function addSectionDialog(){if(state.scope!=='page')return toast('Switch to Page sections to add a section.',true);modal('Add a section',`<p class="small muted">Choose a starting layout. All its text and pictures can be changed.</p><div class="preset-grid">${[['text','Rich text','A heading, paragraph and room for your ideas.'],['image','Image & text','A photograph alongside a message.'],['columns','Three columns','Services, products or ideas side by side.'],['cta','Call to action','A focused message with a next step.']].map(([id,title,desc])=>`<button class="preset" data-preset="${id}"><strong>${title}</strong><span>${desc}</span></button>`).join('')}</div>`)}
function addSection(preset){const d=previewDoc();recordUndo();const main=$('main',d);const templates={text:'<section class="section container"><h2>Your next great idea.</h2><p>Write the message you want visitors to take away.</p></section>',image:'<section class="corporate-intro section container"><div class="intro-photo"><img src="assets/images/technology-guidance.webp" alt="Describe this image" width="1536" height="1024"></div><div class="intro-copy"><h2>A picture. A new perspective.</h2><p>Tell your visitors why this matters.</p><a class="button button-orange" href="contact.html">Start a conversation</a></div></section>',columns:'<section class="section container"><h2>Explore the possibilities.</h2><div class="why-grid"><article><h3>Your first idea</h3><p>Describe what makes this useful.</p></article><article><h3>Your second idea</h3><p>Describe what makes this useful.</p></article><article><h3>Your third idea</h3><p>Describe what makes this useful.</p></article></div></section>',cta:'<section class="page-cta"><div class="container"><div><h2>Ready for your next chapter?</h2><p>Invite your visitors to take the next step.</p></div><a class="button button-orange" href="contact.html">Let’s talk ↗</a></div></section>'};const holder=d.createElement('div');holder.innerHTML=templates[preset];const section=holder.firstElementChild;state.section?state.section.after(section):main.append(section);closeModal();selectElement(section);dirty();section.scrollIntoView({block:'start',behavior:'smooth'})}
async function modifySection(action){const node=state.section;if(!node||state.scope!=='page')return;if(action==='section-delete'&&!await confirmAction('Remove this section?','You can undo this before leaving the editor. The public page changes only after publishing.','Remove section'))return;recordUndo();if(action==='section-up'&&node.previousElementSibling)node.previousElementSibling.before(node);else if(action==='section-down'&&node.nextElementSibling)node.nextElementSibling.after(node);else if(action==='section-duplicate'){const clone=node.cloneNode(true);$$('[id]',clone).forEach(n=>n.removeAttribute('id'));clone.removeAttribute('id');node.after(clone);selectElement(clone)}else if(action==='section-hide'){node.hidden=!node.hidden}else if(action==='section-delete'){node.remove();state.section=null;state.selected=null;renderInspector()}dirty();renderOutline()}
function readMenu(html){const doc=parse(html),nav=$('#navigation',doc);if(!nav)return[];return Array.from(nav.children).map(node=>{if(node.tagName==='DETAILS'){return {label:$('summary',node).textContent.replace(/[⌄↗]/g,'').trim(),url:'',children:$$('.nav-panel>a',node).map(a=>({label:($('strong',a)?.textContent||a.textContent).trim(),url:a.getAttribute('href'),description:$('span',a)?.textContent||'',children:[]}))}}if(node.tagName==='A')return{label:node.textContent.replace(/[↗]/g,'').trim(),url:node.getAttribute('href'),button:node.classList.contains('button'),newTab:node.target==='_blank',children:[]};return null}).filter(Boolean)}
function buildMenuNodes(doc,items,depth=0){return items.map(item=>{if(item.children?.length){const details=doc.createElement('details');details.className='nav-group';const summary=doc.createElement('summary');summary.textContent=item.label+' ';const arrow=doc.createElement('span');arrow.textContent='⌄';arrow.setAttribute('aria-hidden','true');summary.append(arrow);const panel=doc.createElement('div');panel.className='nav-panel';panel.append(...buildMenuNodes(doc,item.children,depth+1));details.append(summary,panel);return details}const a=doc.createElement('a');a.href=item.url||'#';if(item.button)a.className='button button-dark nav-cta';if(item.newTab){a.target='_blank';a.rel='noopener noreferrer'}if(depth){const strong=doc.createElement('strong');strong.textContent=item.label;a.append(strong);if(item.description){const span=doc.createElement('span');span.textContent=item.description;a.append(span)}}else a.textContent=item.label;return a})}
async function loadMenus(){setActive('menus');$('#view').innerHTML='<div class="loading">Opening your navigation…</div>';try{const r=await api('page',null,{slug:'index'});state.menuPage=r.page;state.menu=readMenu(r.page.html);renderMenus()}catch(e){$('#view').innerHTML=`<p class="error">${esc(e.message)}</p>`}}
function menuFields(item,index,child=null){const suffix=`data-menu-index="${index}" ${child!==null?`data-child-index="${child}"`:''}`;return `<div class="menu-fields"><label>Label<input data-menu-field="label" ${suffix} value="${esc(item.label)}"></label><label>Link URL<input data-menu-field="url" ${suffix} value="${esc(item.url||'')}" ${item.children?.length?'disabled':''}></label>${child!==null?`<label style="grid-column:1/-1">Short description<input data-menu-field="description" ${suffix} value="${esc(item.description||'')}"></label>`:''}</div>`}
function renderMenus(){$('#view').innerHTML=header('Menus','Help visitors find their next step. Changes apply across your published pages.',`<button class="btn" data-action="add-menu-link">＋ Add link</button><button class="btn primary" data-action="save-menu">${DEMO?'Save preview menu':'Save menu'}</button>`)+`<div class="menu-layout"><div>${state.menu.map((item,i)=>`<section class="menu-item"><div class="menu-item-head"><span>☷</span>${esc(item.label||'New menu item')}<div class="button-row"><button class="btn sm ghost" data-menu-move="${i}" data-direction="-1" aria-label="Move ${esc(item.label)} up">↑</button><button class="btn sm ghost" data-menu-move="${i}" data-direction="1" aria-label="Move ${esc(item.label)} down">↓</button><button class="btn sm ghost" data-menu-remove="${i}" aria-label="Remove ${esc(item.label)}">✕</button></div></div>${menuFields(item,i)}<label class="check-label" style="margin:13px 0 0"><input type="checkbox" data-menu-field="button" data-menu-index="${i}" ${item.button?'checked':''} ${item.children?.length?'disabled':''}>Display as the main button</label>${item.children?.length?`<div class="menu-children">${item.children.map((child,j)=>`<div class="menu-child">${menuFields(child,i,j)}<div class="button-row"><button class="btn sm ghost" data-child-up="${i}" data-child="${j}">↑</button><button class="btn sm ghost" data-child-down="${i}" data-child="${j}">↓</button><button class="btn sm ghost" data-child-remove="${i}" data-child="${j}">Remove link</button></div></div>`).join('')}</div>`:''}<button class="text-button" style="margin-top:15px" data-add-child="${i}">＋ Add dropdown link</button></section>`).join('')}<button class="btn wide" data-action="add-menu-link">＋ Add another menu item</button></div><aside><div class="menu-preview" id="menu-preview"></div><section class="panel"><div class="panel-body"><h2>Add a page to your menu</h2><label>Choose a page<select id="menu-page-choice">${state.pages.map(p=>`<option value="${esc(p.slug)}">${esc(p.slug==='index'?'Home':p.title)}${p.status==='draft'?' (draft)':''}</option>`).join('')}</select></label><button class="btn wide" data-action="menu-add-page">Add to menu</button><p class="menu-helper" style="margin-top:16px">Publish a draft page before linking visitors to it. Use the arrows to reorder items. Adding a dropdown link turns an item into a menu group.</p></div></section></aside></div>`;renderMenuPreview();$$('[data-menu-field]').forEach(input=>input.oninput=()=>{const item=state.menu[Number(input.dataset.menuIndex)],target=input.dataset.childIndex!==undefined?item.children[Number(input.dataset.childIndex)]:item;state.dirty=true;target[input.dataset.menuField]=input.type==='checkbox'?input.checked:input.value;renderMenuPreview()})}
function renderMenuPreview(){const el=$('#menu-preview');if(el)el.innerHTML='<strong>Your primary menu</strong>'+state.menu.map(item=>`<span>${esc(item.label)}${item.children?.length?' ⌄':''}${(item.children||[]).map(c=>`<small>↳ ${esc(c.label)}</small>`).join('')}</span>`).join('')}
async function saveMenu(){const r=await api('menu',{items:state.menu,revision:state.menuPage.revision});state.pages=r.pages;state.menuPage=r.page;state.dirty=false;toast(DEMO?'Menu saved to local preview drafts. The public website is unchanged.':'Menu updated across your published pages.')}
function renderShared(){$('#view').innerHTML=header('Header & Footer','The shared parts of your site, edited in one place.')+`<div class="settings-grid"><section class="panel"><div class="panel-body"><p class="overline">THE FIRST IMPRESSION</p><h2>Your header</h2><p class="small muted">Edit the brand name, tagline, top bar, navigation text and contact button in the visual editor. Publish once to update every page.</p><button class="btn primary" data-shared="header">Edit shared header →</button><p class="small muted" style="margin:20px 0 0">To add or organize navigation links, use <button class="text-button" data-view="menus">Menus</button>.</p></div></section><section class="panel"><div class="panel-body"><p class="overline">A THOUGHTFUL FINISH</p><h2>Your footer</h2><p class="small muted">Update footer headings, descriptions, links, copyright text and calls to action. Publish once to keep all pages consistent.</p><button class="btn primary" data-shared="footer">Edit shared footer →</button></div></section></div>`}
function renderSettings(){const s=state.settings;$('#view').innerHTML=header('Settings','A few essentials for keeping your website running.')+`<div class="settings-grid"><form id="settings-form" class="panel"><div class="panel-header"><h2>Workspace & enquiries</h2></div><div class="panel-body"><label>Workspace name<input name="siteName" value="${esc(s.siteName||'Next Chapter Collective')}" required maxlength="120"><small>Shown in the admin workspace. Edit your public brand text in Header & Footer.</small></label><label>Receive enquiries at<input name="recipient_email" type="email" value="${esc(s.recipient_email||'')}" placeholder="Your real inbox"><small>This inbox receives website enquiries.</small></label><label>Authorised sender address<input name="sender_email" type="email" value="${esc(s.sender_email||'')}" placeholder="A mailbox on your website domain"><small>Your hosting mail service must allow this sender. Confirm delivery with a real test after setup.</small></label></div><div class="panel-footer"><button class="btn primary" type="submit">Save settings</button></div></form><div><form id="password-form" class="panel"><div class="panel-header"><h2>Owner account</h2></div><div class="panel-body"><label>Username<input value="${esc(s.username||'Site owner')}" readonly></label><label>Current password<input name="currentPassword" type="password" autocomplete="current-password" required ${DEMO?'disabled':''}></label><label>New password<input name="newPassword" type="password" autocomplete="new-password" minlength="12" maxlength="72" required ${DEMO?'disabled':''}><small>Use at least 12 characters.</small></label></div><div class="panel-footer"><button class="btn" type="submit" ${DEMO?'disabled':''}>Update password</button></div></form><section class="panel" style="margin-top:22px"><div class="panel-body"><h2>Keep your website safe</h2><p class="small muted">Use HTTPS on your public domain, keep a copy of your Hostinger backups, and keep your owner credentials and setup key private.</p></div></section></div></div>`;$('#settings-form').onsubmit=async e=>{e.preventDefault();try{const data=Object.fromEntries(new FormData(e.target));const r=await api('settings',data);state.settings=r.settings;$('.topbar-site>span').textContent=r.settings.siteName;toast(DEMO?'Settings saved in this browser only.':'Settings saved.')}catch(e){toast(e.message,true)}};$('#password-form').onsubmit=async e=>{e.preventDefault();try{await api('password',Object.fromEntries(new FormData(e.target)));e.target.reset();toast('Password updated. Other sessions will need to sign in again.')}catch(e){toast(e.message,true)}}}
async function renderTrash(){setActive('trash');$('#view').innerHTML=header('Trash','Restore a page as a private draft when you need it again.')+'<div class="loading">Loading Trash…</div>';try{const r=await api('trash_list');$('#view').innerHTML=header('Trash','Restore a page as a private draft when you need it again.')+`<div class="panel">${r.items.length?`<table class="page-table"><thead><tr><th>PAGE</th><th>MOVED TO TRASH</th><th></th></tr></thead><tbody>${r.items.map(i=>`<tr><td><strong>${esc(i.title)}</strong><span class="page-slug">/${esc(i.slug)}.html</span></td><td>${dateLabel(i.updated)}</td><td><button class="btn sm" data-restore-trash="${esc(i.id)}">Restore as draft</button></td></tr>`).join('')}</tbody></table>`:'<p class="empty-message">No pages in Trash. Pages you move here can be restored as drafts.</p>'}</div>`}catch(e){toast(e.message,true)}}
function renderHelp(){$('#view').innerHTML=header('A little guidance goes a long way.','Everything you need to start making your website your own.')+`<div class="help-grid"><section class="panel"><div class="panel-body"><p class="overline">01 / EDIT YOUR WORDS</p><h2>Text you can work with</h2><p>Open Pages, choose a page, then click text in its preview. Use the rich-text panel to change words, add emphasis, insert lists, align text, add links or choose a text color. Headings and search descriptions can also be changed. On Home, use Hero feature 1, 2 or 3 above the preview to edit each rotating feature, including its text, picture and button.</p><button class="text-button" data-edit="index">Try editing the homepage →</button></div></section><section class="panel"><div class="panel-body"><p class="overline">02 / SHAPE THE PAGE</p><h2>Sections, in your order</h2><p>The section list shows the page’s main areas. Select one to edit its content or use Up, Down, Duplicate, Hide and Remove. Add Section offers rich text, image-and-text, three-column and call-to-action starting layouts.</p></div></section><section class="panel"><div class="panel-body"><p class="overline">03 / ADD YOUR PICTURES</p><h2>A place for your media</h2><p>Upload JPG, PNG, WebP or GIF files in Media Library. Click any picture in the visual editor to replace it, set its crop position and edit its alternative text. Image descriptions help people who cannot see your pictures.</p></div></section><section class="panel"><div class="panel-body"><p class="overline">04 / KEEP THINGS CONSISTENT</p><h2>Shared header and footer</h2><p>Use Header & Footer to edit shared text and pictures. Publishing shared-area edits applies those areas to every published page. Use Menus to add page links, create dropdowns and change the order.</p></div></section><section class="panel"><div class="panel-body"><p class="overline">05 / REVIEW BEFORE SHARING</p><h2>Draft first. Publish when ready.</h2><p>Save Draft keeps changes private. Publish Changes updates the public page. Publishing saves up to 20 previous versions, available under History in the editor. New pages begin as drafts; add them to your menu when ready.</p></div></section><section class="panel"><div class="panel-body"><p class="overline">06 / YOUR WEBSITE SETTINGS</p><h2>Enquiries and owner access</h2><p>Settings lets you choose the enquiry inbox and authorised sending address, and update your owner password. The public site still needs a working hosting mail service and a successful delivery test.</p>${DEMO?'<p><strong>This local preview does not publish or upload to your server.</strong> Its drafts stay in your browser.</p>':''}</div></section></div>`}
async function uploadImage(file){if(DEMO)return toast('Uploads become available after Hostinger setup.',true);if(!file)return;const form=new FormData();form.append('image',file);const r=await api('upload',form);state.media=r.media;toast('Image uploaded.');if(pendingMedia){const cb=pendingMedia;openMediaPicker(cb)}else renderMedia()}
function changeImage(url){if(!state.selected||state.selected.tagName!=='IMG')return;recordUndo();state.selected.src=url;const media=state.media.find(x=>x.url===url);if(media){state.selected.setAttribute('width',media.width);state.selected.setAttribute('height',media.height)}dirty();renderInspector()}
async function handleClick(event){const button=event.target.closest('button,[data-view],[data-edit]');if(!button)return;try{
 if(button.hasAttribute('data-modal-close')){closeModal();return}
 if(button.dataset.view){await safeNavigate(button.dataset.view);return}
 if(button.dataset.edit){await openEditor(button.dataset.edit);return}
 if(button.dataset.shared){await openEditor('index',button.dataset.shared);return}
 if(button.dataset.pageFilter){state.filter=button.dataset.pageFilter;renderPages();return}
 if(button.dataset.sectionIndex!==undefined){const node=sectionNodes()[Number(button.dataset.sectionIndex)];selectElement(node);node.scrollIntoView({block:'start',behavior:'smooth'});return}
 if(button.dataset.inspector){state.tab=button.dataset.inspector;renderInspector();return}
 if(button.dataset.previewSize){$('#preview-wrap').classList.toggle('phone',button.dataset.previewSize==='phone');return}
 if(button.dataset.rich){await runRich(button.dataset.rich);return}
 if(button.dataset.preset){addSection(button.dataset.preset);return}
 if(button.dataset.pickMedia){const callback=pendingMedia;const url=button.dataset.pickMedia;closeModal();callback?.(url);return}
 if(button.dataset.mediaDetail){showMediaDetail(button.dataset.mediaDetail);return}
 if(button.dataset.trash){if(!await confirmAction('Move this page to Trash?','The public page will be removed. Existing links may need updating. You can restore it later as a draft.','Move to Trash'))return;const r=await api('trash',{slug:button.dataset.trash});state.pages=r.pages;renderPages();toast('Page moved to Trash.');return}
 if(button.dataset.restoreTrash){const r=await api('restore_trash',{id:button.dataset.restoreTrash});state.pages=r.pages;loadEditor(r.page);toast('Page restored as a draft.');return}
 if(button.dataset.restoreRevision){if(!await confirmAction('Restore this version?','This will replace the public page. The current public page will be saved as another revision.','Restore version'))return;const r=await api('restore_revision',{slug:state.current.slug,id:button.dataset.restoreRevision,revision:state.current.revision});state.pages=r.pages;loadEditor(r.page);toast('Previous version restored.');return}
 if(button.dataset.menuMove!==undefined){const index=Number(button.dataset.menuMove),next=index+Number(button.dataset.direction);if(next>=0&&next<state.menu.length)[state.menu[index],state.menu[next]]=[state.menu[next],state.menu[index]];state.dirty=true;renderMenus();return}
 if(button.dataset.menuRemove!==undefined){state.menu.splice(Number(button.dataset.menuRemove),1);state.dirty=true;renderMenus();return}
 if(button.dataset.addChild!==undefined){const item=state.menu[Number(button.dataset.addChild)];item.button=false;(item.children??=[]).push({label:'New link',url:'contact.html',description:'',children:[]});state.dirty=true;renderMenus();return}
 for(const key of ['childUp','childDown','childRemove'])if(button.dataset[key]!==undefined){const list=state.menu[Number(button.dataset[key])].children,index=Number(button.dataset.child);if(key==='childRemove')list.splice(index,1);else{const next=index+(key==='childUp'?-1:1);if(next>=0&&next<list.length)[list[index],list[next]]=[list[next],list[index]]}state.dirty=true;renderMenus();return}
 const action=button.dataset.action;if(!action)return;
 if(action==='new-page')newPageDialog();
 else if(action==='create-page')await createPage();
 else if(action==='save-draft')await saveDraft();
 else if(action==='publish')await publish();
 else if(action==='undo'){const html=state.undo.pop();if(!html)return toast('No earlier changes in this editing session.');state.selected=null;state.section=null;mountPreview(html);dirty();renderInspector()}
 else if(action==='add-section')addSectionDialog();
 else if(action.startsWith('section-'))await modifySection(action);
 else if(action==='replace-image')openMediaPicker(changeImage);
 else if(action==='apply-source'){recordUndo();const html=$('#page-source').value;mountPreview(html);dirty();state.selected=null;state.section=null;state.tab='content';renderInspector();toast('HTML applied to the preview. Review it before publishing.')}
 else if(action==='discard-draft'){if(!await confirmAction('Discard the saved draft?','The public page will stay unchanged. Your saved draft changes will be removed.','Discard draft'))return;const r=await api('discard',{slug:state.current.slug});state.pages=r.pages;loadEditor(r.page);toast('Draft discarded.')}
 else if(action==='insert-rich-link'){const url=$('#rich-link-value').value;if(!validUrl(url)||!url)return toast('Enter a valid link.',true);closeModal();restoreRange();document.execCommand('createLink',false,url);applyRichText();captureRange()}
 else if(action==='upload')$('#media-upload').click();
 else if(action==='save-menu')await saveMenu();
 else if(action==='add-menu-link'){state.menu.push({label:'New link',url:'contact.html',button:false,children:[]});state.dirty=true;renderMenus()}
 else if(action==='menu-add-page'){const slug=$('#menu-page-choice').value,p=state.pages.find(x=>x.slug===slug);state.menu.push({label:slug==='index'?'Home':p.title,url:slug+'.html',button:false,children:[]});state.dirty=true;renderMenus()}
 else if(action==='logout'){if(DEMO)return toast('You are viewing a local preview. No owner account is signed in.');if(state.dirty&&!await confirmAction('Sign out?','You have unsaved edits. Save your changes first if you want to keep them.','Sign out'))return;await api('logout',{});state.dirty=false;renderAuth(false)}
 else if(action==='reset-demo'){if(!await confirmAction('Reset this local preview?','This removes only the preview drafts in this browser. Your public website will stay unchanged.','Reset preview'))return;localStorage.removeItem('ncc-admin-demo-v1');state.dirty=false;location.reload()}
 }catch(e){toast(e.message,true)}}
document.addEventListener('click',handleClick);
$('.sidebar-toggle').addEventListener('click',()=>document.body.classList.toggle('sidebar-open'));
$('#media-upload').addEventListener('change',async e=>{try{await uploadImage(e.target.files[0])}catch(e){toast(e.message,true)}e.target.value=''});
$('#auth-form').addEventListener('submit',async event=>{event.preventDefault();const button=$('#auth-submit');button.disabled=true;$('#auth-error').textContent='';try{const data=Object.fromEntries(new FormData(event.target));const r=await api(event.target.dataset.mode||'login',data);$('#user-name').textContent=r.username;event.target.reset();await enterApp()}catch(e){$('#auth-error').textContent=e.message}finally{button.disabled=false}});
window.addEventListener('beforeunload',event=>{if(state.dirty){event.preventDefault();event.returnValue=''}});
boot();

function syncHero(){const d=previewDoc();if(!d)return;const feature=d.querySelectorAll('[data-hero-library] [data-feature]')[state.heroIndex||0];if(!feature)return;const h=d.getElementById('hero-heading'),p=d.getElementById('hero-description'),a=d.getElementById('hero-primary-link'),img=d.getElementById('hero-image');if(h)feature.querySelector('h2').innerHTML=h.innerHTML;if(p)feature.querySelector('p').innerHTML=p.innerHTML;if(a){feature.querySelector('a').innerHTML=a.innerHTML.replace(/<span[^>]*aria-hidden[^>]*>.*?<\/span>/g,'').trim();feature.querySelector('a').setAttribute('href',a.getAttribute('href'));}if(img){feature.querySelector('img').setAttribute('src',img.getAttribute('src'));feature.querySelector('img').alt=img.alt;}}
function showEditorHero(){const d=previewDoc(),feature=d.querySelectorAll('[data-hero-library] [data-feature]')[state.heroIndex||0];if(!feature)return;d.getElementById('hero-heading').innerHTML=feature.querySelector('h2').innerHTML;d.getElementById('hero-description').innerHTML=feature.querySelector('p').innerHTML;const a=d.getElementById('hero-primary-link');a.innerHTML=feature.querySelector('a').innerHTML+' <span aria-hidden="true">↗</span>';a.setAttribute('href',feature.querySelector('a').getAttribute('href'));const img=d.getElementById('hero-image'),saved=feature.querySelector('img');img.setAttribute('src',saved.getAttribute('src'));img.alt=saved.alt;selectElement(d.getElementById('hero-heading'));d.getElementById('hero-heading').scrollIntoView({block:'center'});}
